## Why This Is Asked
Tests a three-dimensional DP that models constrained path planning with a binary obstacle grid and a budget of unblocks. Requires careful state definition, transitions, and path reconstruction. 

## Key Concepts
- DP with an extra dimension for unblocks (t)
- Handling blocked vs unblocked cells in transitions
- Path reconstruction from 3D DP table
- Time/space trade-offs and rolling optimization

## Code Example
```javascript
function maxPath(grid, blocked, k) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () => Array.from({length: m}, () => Array(k+1).fill(NEG)));
  if (!blocked[0][0]) dp[0][0][0] = grid[0][0];
  else if (k > 0) dp[0][0][1] = grid[0][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        const val = grid[i][j];
        if (i > 0) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t] + val * (blocked[i][j] ? 0 : 1));
          if (blocked[i][j] && t > 0) dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t-1] + val);
        }
        if (j > 0) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t] + val * (blocked[i][j] ? 0 : 1));
          if (blocked[i][j] && t > 0) dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t-1] + val);
        }
      }
    }
  }
  return dp[n-1][m-1][0];
}
```

## Follow-up Questions
- How would you recover the actual path from the 3D DP and handle ties?
- What optimizations would you apply for large grids or memory constraints?

## Why This Is Asked
Tests DP over time with multiple constraints: multiple transactions, reconstruction, and edge-case handling.

## Key Concepts
- Two DP states: cash (not holding) and hold (holding).
- Transitions model buy/sell with transaction count t.
- Base cases initialize day 0; backtracking recovers trade days.
- Space optimization possible to O(k) with rolling arrays.

## Code Example
```javascript
function maxProfit(prices, k){
  const n = prices.length;
  if (n===0 || k===0) return 0;
  const cash = Array.from({length:n+1}, ()=> Array(k+1).fill(-1e15));
  const hold = Array.from({length:n+1}, ()=> Array(k+1).fill(-1e15));
  for (let t=0; t<=k; t++) cash[0][t] = (t===0)?0:-1e15;
  for (let i=1; i<=n; i++){
    for (let t=0; t<=k; t++){
      cash[i][t] = cash[i-1][t];
      if (t>0) cash[i][t] = Math.max(cash[i][t], hold[i-1][t] + prices[i-1]);
      hold[i][t] = hold[i-1][t];
      if (t>0) hold[i][t] = Math.max(hold[i][t], cash[i-1][t-1] - prices[i-1]);
    }
  }
  let best = 0;
  for (let t=0; t<=k; t++) best = Math.max(best, cash[n][t]);
  return best;
}
```

## Follow-up Questions
- How would you recover the exact trade days from the DP table?
- How does the solution change if k >= n/2 (unlimited transactions)?

## Why This Is Asked
Tests ability to design a DP with a non-trivial cost function and prefix optimization.

## Key Concepts
- DP on prefixes and partitions
- O(1) substring cost via precomputed diff/pref
- Path reconstruction via parent pointers

## Code Example
```javascript
// Precompute diff and prefix
let diff = Array(n+1).fill(0);
for (let i=2;i<=n;i++) diff[i] = s[i-1] !== s[i-2] ? 1:0;
let pref = Array(n+1).fill(0);
for (let i=2;i<=n;i++) pref[i] = pref[i-1] + diff[i];

// cost(a,b)
function cost(a,b){ return pref[b] - pref[a]; }

// DP
let dp = Array.from({length:n+1}, ()=> Array(k+1).fill(Infinity));
let par = Array.from({length:n+1}, ()=> Array(k+1).fill(-1));
for(let i=1;i<=n;i++){ dp[i][1] = cost(1,i); }

for(let t=2;t<=k;t++){
  for(let i=t;i<=n;i++){
    for(let p=t-1;p<=i-1;p++){
      let val = dp[p][t-1] + cost(p+1,i);
      if(val < dp[i][t]){ dp[i][t] = val; par[i][t] = p; }
    }
  }
}
```

## Follow-up Questions
- How could you optimize to O(nk) with divide-and-conquer DP if cost satisfies quadrangle inequality?
- How would you extract the actual partition end indices from par?

## Why This Is Asked
This problem tests your ability to structure a dynamic programming solution for exact-k resource selection with non-overlapping intervals. It requires combining weighted interval scheduling with a prefix DP over both task count and index, along with binary search for efficient predecessor lookup and clean reconstruction.

## Key Concepts
- Weighted interval scheduling with exact k constraint
- Prefix DP over tasks (i) and count (t)
- Precomputing p[i] via binary search for O(log n) lookups
- Backtracking through DP table for reconstruction

## Code Example
```javascript
function weightedIntervalScheduling(tasks, K) {
  // Sort by end time
  tasks.sort((a, b) => a.end - b.end);
  const n = tasks.length;

  // Precompute p[i] - last non-overlapping task
  const ends = tasks.map(t => t.end);
  const p = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    let lo = 0, hi = i - 1, res = -1;
    while (lo <= hi) {
      const mid = Math.floor) / 2((lo + hi);
      if (tasks[mid].end <= tasks[i].start) {
        res = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    p[i] = res;
  }

  // DP table: dp[i][t] = max value using first i tasks for t selections
  const dp = Array.from({ length: n + 1 }, () => Array(K + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= K; t++) {
      // Skip task i-1
      dp[i][t] = dp[i - 1][t];
      // Take task i-1
      if (p[i - 1] !== -1) {
        dp[i][t] = Math.max(dp[i][t], dp[p[i - 1] + 1][t - 1] + tasks[i - 1].value);
      } else if (t === 1) {
        dp[i][t] = Math.max(dp[i][t], tasks[i - 1].value);
      }
    }
  }

  // Reconstruction
  const chosen = [];
  let i = n, t = K;
  while (i > 0 && t > 0) {
    if (dp[i][t] === dp[i - 1][t]) {
      i--;
    } else {
      chosen.push(i - 1);
      const prev = p[i - 1];
      i = prev + 1;
      t--;
    }
  }

  return { maxValue: dp[n][K], chosenTasks: chosen.reverse() };
}
```

## Why This Is Asked

This problem tests partitioning a sequence into exactly k blocks where block value is non-linear in length. It requires a careful DP with reconstruction and shows understanding of prefix sums and state transitions.

## Key Concepts

- DP over partitions
- Prefix sums for O(1) subarray sums
- Non-linear block value and reconstruction
- Time/space trade-offs: O(n^2 k) time, O(nk) space

## Code Example

```javascript
function maxKSubarraysProduct(a, k) {
  const n = a.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i-1] + a[i-1];
  const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(-Infinity));
  const pick = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1][t];
      for (let j = 1; j <= i; j++) {
        const val = dp[j-1][t-1] + (i - j + 1) * (pref[i] - pref[j-1]);
        if (val > dp[i][t]) {
          dp[i][t] = val;
          pick[i][t] = j;
        }
      }
    }
  }
  // reconstruction omitted for brevity
  return dp[n][k];
}
```

## Follow-up Questions

- How would you optimize to O(nk) time with monotone queue or divide-and-conquer tricks?
- How would you handle allowing at most k blocks and a penalty for unused blocks?

## Why This Is Asked
Tests concrete DP skills on string partitioning with reconstruction; approachable for beginners yet non-trivial.

## Key Concepts
- dp[i][t]: maximum sum for first i digits split into t parts
- val(j,i): integer value of s[j..i-1] (leading zeros allowed)
- transition: dp[i][t] = max_{j ∈ [t-1..i-1]} dp[j][t-1] + val(j,i)
- reconstruction: track prev to recover split indices
- complexity: O(n²k) time, O(nk) space; use BigInt for large results

## Code Example
```javascript
function maxSumSplit(s, k){
  const n = s.length;
  const val = (a,b)=> BigInt(s.slice(a,b));
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-1n));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  for(let i=1;i<=n;i++){
    dp[i][1] = val(0,i);
  }

  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<i;j++){
        const candidate = dp[j][t-1] + val(j,i);
        if(candidate > dp[i][t]){
          dp[i][t] = candidate;
          prev[i][t] = j;
        }
      }
    }
  }

  // Reconstruct splits
  const splits = [];
  let curr = n, parts = k;
  while(parts > 1){
    const j = prev[curr][parts];
    splits.push(j);
    curr = j;
    parts--;
  }
  splits.reverse();

  return {maxSum: dp[n][k], splits};
}
```

## Why This Is Asked
Tests a classic DP over partitioning with a non-linear segment cost (max). It checks understanding of states, transitions, and reconstruction, plus edge cases like k=1 and k=n.

## Key Concepts
- DP over partitions: dp[i][t] for first i elements into t segments
- Segment cost as max over A[j..i-1] and dynamic maintenance of that max
- Reconstruction of endpoints via parent pointers

## Code Example
```javascript
function minSumMaxPartitions(A, k) {
  const n = A.length;
  const INF = 1e15;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(INF));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      let mx = -Infinity;
      for (let j = i - 1; j >= 0; j--) {
        mx = Math.max(mx, A[j]);
        if (dp[j][t - 1] !== INF) {
          dp[i][t] = Math.min(dp[i][t], dp[j][t - 1] + mx);
        }
      }
    }
  }
  return dp[n][k];
}
```

## Follow-up Questions
- How would you reconstruct the exact endpoints efficiently?
- Can you optimize to O(nk) with additional structure or pruning for typical inputs?

## Why This Is Asked
Tests DP design for selecting multiple disjoint subarrays with reconstruction. Requires prefix sums, state definition, and backtracking.

## Key Concepts
- DP over positions and count of subarrays
- Prefix sums for subarray sums
- Reconstructing intervals with predecessor pointers
- Time/space trade-offs (O(nk) vs optimizations)

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length; const P = new Array(n+1).fill(0);
  for (let i=1;i<=n;i++) P[i] = P[i-1] + A[i-1];
  const dp = Array.from({length:n+1}, ()=>new Array(k+1).fill(-Infinity));
  const from = Array.from({length:n+1}, ()=>new Array(k+1).fill(null));
  for (let i=0;i<=n;i++) dp[i][0] = 0;
  for (let t=1;t<=k;t++){
    let best = -Infinity;
    let bestIdx = -1;
    for (let i=1;i<=n;i++){
      if (dp[i-1][t-1] - P[i-1] > best){ best = dp[i-1][t-1] - P[i-1]; bestIdx = i-1; }
      const take = P[i] + best;
      if (take > dp[i-1][t]){ dp[i][t] = take; from[i][t] = [bestIdx+1, i]; }
      else { dp[i][t] = dp[i-1][t]; }
    }
  }
  // reconstruction (omitted for brevity in this snippet)
  return {maxSum: dp[n][k], intervals: []};
}
```

## Follow-up Questions
- How would you handle exactly k vs at most k subarrays?
- Can you reduce space to O(n) or O(k)?
- How would you reconstruct intervals efficiently without extra passes?

## Why This Is Asked
This question tests DP with a constrained path problem and reconstruction, a common real interview topic for large-scale environments like PayPal or Cloudflare.

## Key Concepts
- 4D DP state: i, j, t, dir (0 right, 1 down)
- Turn counting via transition from one dir to the other
- Base cases for first row/column
- Path reconstruction pointers and memory/time trade-offs

## Code Example
```javascript
function maxPathWithTurns(grid, k) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () =>
      Array.from({length: k+1}, () => [NEG, NEG])
    )
  );
  dp[0][0][0][0] = grid[0][0];
  for (let j = 1; j < m; j++) dp[0][j][0][0] = dp[0][j-1][0][0] + grid[0][j];
  for (let i = 1; i < n; i++) dp[i][0][0][1] = dp[i-1][0][0][1] + grid[i][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        if (j > 0) {
          const fromLeftSame = dp[i][j-1][t][0];
          const fromLeftTurn = t > 0 ? dp[i][j-1][t-1][1] : NEG;
          dp[i][j][t][0] = Math.max(dp[i][j][t][0], grid[i][j] + Math.max(fromLeftSame, fromLeftTurn));
        }
        if (i > 0) {
          const fromTopSame = dp[i-1][j][t][1];
          const fromTopTurn = t > 0 ? dp[i-1][j][t-1][0] : NEG;
          dp[i][j][t][1] = Math.max(dp[i][j][t][1], grid[i][j] + Math.max(fromTopSame, fromTopTurn));
        }
      }
    }
  }
  let best = NEG, bestT = 0, bestDir = 0;
  for (let t = 0; t <= k; t++) {
    for (let d = 0; d < 2; d++) {
      if (dp[n-1][m-1][t][d] > best) {
        best = dp[n-1][m-1][t][d]; bestT = t; bestDir = d;
      }
    }
  }
  return {best, bestT, bestDir};
}
```

## Follow-up Questions
- How would you reconstruct the path coordinates efficiently?
- Can you optimize memory to O(n*m*k) or O(k) with rolling arrays?

## Why This Is Asked
Explores a new DP angle: subarray-level min as value, exact k non-overlapping blocks, with clear reconstruction.

## Key Concepts
- Partition DP with exact block count
- Precomputation of subarray minima
- Backtracking to obtain endpoints

## Code Example
```javascript
// Assumes A is 1-indexed, n = A.length-1, k given
function maxSumMinSubarrays(A, n, k) {
  const M = Array.from({length: n+2}, ()=>Array(n+2).fill(0));
  for (let l=1; l<=n; l++) {
    let m = A[l];
    for (let r=l; r<=n; r++) {
      m = Math.min(m, A[r]);
      M[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, ()=>Array(k+1).fill(-Infinity));
  const opt = Array.from({length: n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=1; t<=k; t++) {
      for (let l=1; l<=i; l++) {
        const cand = dp[l-1][t-1] + M[l][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; opt[i][t] = l; }
      }
    }
  }
  // backtrack for endpoints
  let i = n, t = k, blocks = [];
  while (t > 0) {
    const l = opt[i][t];
    blocks.push([l, i]);
    i = l-1; t--;
  }
  blocks.reverse();
  return {sum: dp[n][k], blocks};
}
```

## Why This Is Asked

Tests a new DP angle on strings with deletions, requiring careful handling of multiple transitional options (match, delete ends, delete both) and reconstruction under a budget. It extends longest palindromic subsequence with a deletions constraint, common in intermediate interviews.

## Key Concepts

- 3D DP state dp[i][j][t]
- Transitions: match, delete left, delete right, delete both
- Reconstruction via parent pointers
- Time/space: O(n^2 k)
- Edge cases: k may exceed n, i==j base

## Code Example

```javascript
function maxPalLenWithDeletions(s, k) {
  const n = s.length;
  const dp = Array.from({length: n}, ()=> Array.from({length: n}, ()=> Array(k+1).fill(0)));
  for (let i=0;i<n;i++) dp[i][i][0]=1;
  for (let len=2; len<=n; len++){
    for (let i=0; i+len-1<n; i++){
      const j = i+len-1;
      for (let t=0; t<=k; t++){
        if (s[i]===s[j] && t>=0){
          dp[i][j][t] = Math.max(dp[i][j][t], (i+1<=j-1 ? dp[i+1][j-1][t] : 0) + 2);
        }
        if (t>0){
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i+1][j][t-1], dp[i][j-1][t-1]);
        }
        if (t>1){
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i+1][j-1][t-2]);
        }
      }
    }
  }
  let ans = 0;
  for (let t=0;t<=k;t++) ans = Math.max(ans, dp[0][n-1][t]);
  return ans;
}
```

